const companies = $input.first().json.companies ?? [];
const lcaCounts = $input.first().json.lcaCounts ?? [];

if (companies.length !== lcaCounts.length) {
  throw new Error(
    `Different array lengths: ${companies.length} companies and ${lcaCounts.length} LCA counts`
  );
}

return companies.map((company, index) => ({
  json: {
    company,
    lcaCount: Number(
      String(lcaCounts[index] ?? '').replace(/,/g, '')
    ),
  },
}));

const items = $input.all().map((item) => item.json);

// Collect all prepared job records
const jobs = items.filter(
  (item) => item.id && item.title && item.applyUrl
);

// Collect all sponsor records
const sponsors = items.filter(
  (item) =>
    item.company &&
    typeof item.lcaCount === 'number' &&
    !item.id
);

if (jobs.length === 0) {
  throw new Error('No prepared job records were found');
}

if (sponsors.length === 0) {
  throw new Error('No sponsor records were found');
}

function normalizeCompanyName(name) {
  return String(name ?? '')
    .toLowerCase()
    .replace(
      /\b(incorporated|corporation|company|limited|llc|inc|corp|ltd|usa|us)\b/g,
      ''
    )
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

return jobs.map((job) => {
  const normalizedCompany = normalizeCompanyName(job.company);

  const matchedSponsor = sponsors.find((sponsor) => {
    const normalizedSponsor = normalizeCompanyName(sponsor.company);

    return (
      normalizedCompany === normalizedSponsor ||
      normalizedCompany.includes(normalizedSponsor) ||
      normalizedSponsor.includes(normalizedCompany)
    );
  });

  return {
    json: {
      ...job,
      normalizedCompany,
      hasSponsorHistory: Boolean(matchedSponsor),
      matchedSponsorName: matchedSponsor?.company ?? null,
      lcaCount: matchedSponsor?.lcaCount ?? 0,
    },
  };
});

const descriptionHtml =
  $json.job?.job_information?.description ?? '';

// Convert the HTML description into readable plain text
const descriptionText = descriptionHtml
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|li|div|h[1-6]|ul|ol)>/gi, '\n')
  .replace(/<li[^>]*>/gi, '- ')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\n[ \t]+/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const resolvedCompany =
  $json.company_identity?.recommendedCompanyName ?? '';

return {
  json: {
    // Preserve EVERYTHING we've accumulated so far
    ...$json,

    // Normalized fields used by downstream nodes
    title:
      $json.job_information?.title ??
      $json.v5_processed_job_data?.core_job_title ??
      '',

    company: resolvedCompany,

    applyUrl: $json.apply_url ?? '',

    requirementsSummary:
      $json.v5_processed_job_data?.requirements_summary ?? '',

    technicalTools:
      $json.v5_processed_job_data?.technical_tools ?? [],

    descriptionHtml,
    descriptionText,
  },
};

const sponsorEntityName = String(
  $json.sponsor_entity_mapping?.['Verified Sponsor Entity Name'] ?? ''
).trim();

if (!sponsorEntityName) {
  throw new Error('No verified sponsor entity available for sponsor search.');
}

return {
  json: {
    ...$json,
    sponsorSearchTerm: sponsorEntityName,
  },
};

const html = $input.first().json.data;

const match = html.match(
  /<script[^>]*id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/
);

if (!match) {
  throw new Error("__NEXT_DATA__ not found");
}

const nextData = JSON.parse(match[1]);

const jobs = nextData.props?.pageProps?.ssrHits;

if (!Array.isArray(jobs)) {
  throw new Error("Expected props.pageProps.ssrHits to be an array");
}

return jobs.map((job) => ({
  json: job,
}));

const jobRecord = $('Merge Job Metadata + Description').item.json;
const companyIdentity = $json.output;

return {
  json: {
    ...jobRecord,
    company_identity: companyIdentity,
  },
};

const jobs = $('Prepare Job Record').all().map(item => item.json);

// Remove the empty {} produced by "Always Output Data"
const mappings = $input.all()
  .map(item => item.json)
  .filter(mapping => Object.keys(mapping).length > 0);

function normalize(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

// Build reusable lookup by Company Identity
const mappingByCompany = new Map();

for (const mapping of mappings) {
  const key = normalize(mapping['Company Identity']);

  if (key) {
    mappingByCompany.set(key, mapping);
  }
}

return jobs.map(job => {
  const mapping =
    mappingByCompany.get(normalize(job.company)) ?? null;

  return {
    json: {
      ...job,

      sponsor_entity_mapping: mapping,

      hasSponsorEntityMapping: Boolean(
        mapping &&
        mapping['Mapping Status'] === 'Verified' &&
        mapping['Verified Sponsor Entity Name']
      ),
    },
  };
});

const html = String($json.data ?? '');

// Recover the complete job record that entered the HTTP request
const job = $('Prepare Sponsor Search').item.json;

// Detect an explicit no-results response
const noResults =
  /returns\s+no\s+results/i.test(html);

// Extract the result table row
const rowRegex =
  /<tr>\s*<td>1<\/td>\s*<td>(.*?)<\/td>\s*<td[^>]*>\s*<a\s+href=['"]([^'"]+)['"][^>]*>(.*?)<\/td>\s*<td>(.*?)<\/td>\s*<td>(.*?)<\/td>\s*<\/tr>/is;

const match = html.match(rowRegex);

function clean(value) {
  return String(value ?? '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

let sponsorLookup = {
  searchTerm: job.sponsorSearchTerm ?? '',
  found: false,
  resultCount: 0,
  employerName: null,
  employerPath: null,
  visaRank: null,
  h1bDeniedOrWithdrawn: null,
  h1bTotalApplications: null,
  greenCardDeniedOrWithdrawn: null,
  greenCardTotalApplications: null,
};

if (!noResults && match) {
  const visaRank = clean(match[1]);
  const employerPath = clean(match[2]);
  const employerName = clean(match[3]);

  const h1b = clean(match[4]).match(/(\d+)\s*\/\s*(\d+)/);
  const greenCard = clean(match[5]).match(/(\d+)\s*\/\s*(\d+)/);

  sponsorLookup = {
    ...sponsorLookup,
    found: true,
    resultCount: 1,
    employerName,
    employerPath,
    visaRank: visaRank === '-' ? null : Number(visaRank),

    h1bDeniedOrWithdrawn: h1b ? Number(h1b[1]) : null,
    h1bTotalApplications: h1b ? Number(h1b[2]) : null,

    greenCardDeniedOrWithdrawn: greenCard ? Number(greenCard[1]) : null,
    greenCardTotalApplications: greenCard ? Number(greenCard[2]) : null,
  };
}

return {
  json: {
    ...job,
    sponsor_lookup: sponsorLookup,
  },
};

const lookup = $json.sponsor_lookup ?? {};

let sponsorHistoryStatus;

if (!lookup.found) {
  sponsorHistoryStatus = 'LOOKUP_UNRESOLVED';
} else if (
  Number.isFinite(lookup.h1bTotalApplications) &&
  lookup.h1bTotalApplications > 0
) {
  sponsorHistoryStatus = 'HAS_H1B_HISTORY';
} else if (
  Number.isFinite(lookup.h1bTotalApplications) &&
  lookup.h1bTotalApplications === 0
) {
  sponsorHistoryStatus = 'NO_H1B_HISTORY_FOUND';
} else {
  sponsorHistoryStatus = 'LOOKUP_UNRESOLVED';
}

return {
  json: {
    ...$json,

    sponsor_history: {
      status: sponsorHistoryStatus,
      hasRecentH1BHistory:
        sponsorHistoryStatus === 'HAS_H1B_HISTORY',

      h1bTotalApplications:
        lookup.h1bTotalApplications ?? null,

      h1bDeniedOrWithdrawn:
        lookup.h1bDeniedOrWithdrawn ?? null,

      visaRank:
        lookup.visaRank ?? null,

      matchedEmployer:
        lookup.employerName ?? null,
    },
  },
};

const text = String($json.descriptionText ?? '')
  .replace(/\s+/g, ' ')
  .trim();

const noSponsorshipPatterns = [
  /(?:does not|doesn't|do not|don't|will not|won't|cannot|can't)\s+(?:provide|offer|support)?\s*(?:employment|visa|immigration)?\s*sponsorship/i,

  /no\s+(?:employment|visa|immigration)?\s*sponsorship/i,

  /without\s+(?:current or future\s+)?(?:employment|visa|immigration)?\s*sponsorship/i,

  /not\s+(?:eligible|available)\s+for\s+(?:employment|visa|immigration)?\s*sponsorship/i,

  /must\s+(?:be\s+)?(?:currently\s+)?authorized\s+to\s+work\s+in\s+the\s+(?:u\.?s\.?|united states)\s+without\s+(?:current or future\s+)?sponsorship/i,

  /unable\s+to\s+(?:provide|offer|support)\s+(?:employment|visa|immigration)?\s*sponsorship/i,
];

const sponsorshipAvailablePatterns = [
  /visa\s+sponsorship\s+(?:is\s+)?available/i,
  /sponsorship\s+(?:is\s+)?available/i,
  /we\s+(?:provide|offer|support)\s+(?:employment|visa|immigration)?\s*sponsorship/i,
];

const noMatches = noSponsorshipPatterns
  .filter(pattern => pattern.test(text))
  .map(pattern => pattern.source);

const yesMatches = sponsorshipAvailablePatterns
  .filter(pattern => pattern.test(text))
  .map(pattern => pattern.source);

let status = 'NOT_STATED';

if (noMatches.length > 0 && yesMatches.length > 0) {
  status = 'AMBIGUOUS';
} else if (noMatches.length > 0) {
  status = 'EXPLICIT_NO_SPONSORSHIP';
} else if (yesMatches.length > 0) {
  status = 'EXPLICIT_SPONSORSHIP_AVAILABLE';
}

return {
  json: {
    ...$json,

    job_sponsorship: {
      status,
      explicitRestrictionFound: status === 'EXPLICIT_NO_SPONSORSHIP',
      explicitAvailabilityFound:
        status === 'EXPLICIT_SPONSORSHIP_AVAILABLE',
      matchedNoSponsorshipPatterns: noMatches,
      matchedSponsorshipAvailablePatterns: yesMatches,
    },
  },
};
